/* MarginPad Cloudflare Worker:
   - /api/*            → public JSON calculator API (CORS-enabled)
   - /api/prices       → live prices (proxied + cached + fallback)
   - /telegram/webhook → Telegram bot with inline-button UI (needs TELEGRAM_TOKEN secret)
   - everything else   → static assets (the website) */

const CORS = {
  'access-control-allow-origin': '*',
  'access-control-allow-methods': 'GET, OPTIONS',
  'access-control-allow-headers': 'Content-Type',
};
const round = (n, d = 6) => { if (!isFinite(n)) return null; const f = Math.pow(10, d); return Math.round(n * f) / f; };
const J = (obj, status = 200) =>
  new Response(JSON.stringify(obj, null, 2) + '\n', {
    status, headers: { 'content-type': 'application/json; charset=utf-8', 'cache-control': 'no-store', ...CORS },
  });
const num = (p, k) => { const v = parseFloat(p.get(k)); return isFinite(v) ? v : NaN; };

// ---------- calculations ----------
function calcLiquidation(p) {
  const entry = num(p, 'entry'), lev = num(p, 'leverage');
  const mmr = (isFinite(num(p, 'mmr')) ? num(p, 'mmr') : 0.5) / 100;
  const side = (p.get('side') || 'long').toLowerCase();
  if (!isFinite(entry) || !isFinite(lev) || lev <= 0) return J({ error: 'Required: entry, leverage (>0). Optional: mmr, side.' }, 400);
  const long = side !== 'short';
  // Formula matches the paper-trade sim (liqOf/metrics/add) so the calculator and the terminal agree, AND it never
  // inverts: the old `entry*(1-1/lev+mmr)` printed liq AT/ABOVE entry once lev >= 1/mmr (=200× at mmr 0.5%). This form
  // keeps a long's liq strictly in (0, entry) and a short's above entry for every leverage up to 1000×.
  const liq = mpcLiq(entry, lev, mmr, long);
  return J({ entry, leverage: lev, maintenanceMarginRate: mmr * 100, side: long ? 'long' : 'short', liquidationPrice: round(liq, 2), distancePct: round((liq - entry) / entry * 100, 2) });
}
function calcPositionSize(p) {
  const balance = num(p, 'balance'), risk = num(p, 'risk') / 100, entry = num(p, 'entry'), stop = num(p, 'stop'), lev = num(p, 'leverage');
  const dist = Math.abs(entry - stop);
  if (!isFinite(balance) || !isFinite(risk) || !isFinite(entry) || !isFinite(stop) || dist === 0) return J({ error: 'Required: balance, risk, entry, stop (entry≠stop). Optional: leverage.' }, 400);
  const riskAmount = balance * risk, size = riskAmount / dist, notional = size * entry;
  return J({ balance, riskPct: risk * 100, entry, stop, positionSize: round(size), notional: round(notional, 2), riskAmount: round(riskAmount, 2), stopDistancePct: round(dist / entry * 100, 2), marginRequired: (isFinite(lev) && lev > 0) ? round(notional / lev, 2) : null });
}
function calcPnl(p) {
  const entry = num(p, 'entry'), exit = num(p, 'exit'), size = num(p, 'size'), lev = num(p, 'leverage');
  const side = (p.get('side') || 'long').toLowerCase();
  if (!isFinite(entry) || !isFinite(exit) || !isFinite(size)) return J({ error: 'Required: entry, exit, size. Optional: leverage, side.' }, 400);
  const long = side !== 'short';
  const pnl = (long ? (exit - entry) : (entry - exit)) * size;
  const roi = (long ? (exit - entry) : (entry - exit)) / entry * 100;
  return J({ entry, exit, size, side: long ? 'long' : 'short', pnl: round(pnl, 2), roiPct: round(roi, 2), roePct: (isFinite(lev) && lev > 0) ? round(roi * lev, 2) : null, entryNotional: round(entry * size, 2) });
}
function calcRiskReward(p) {
  const entry = num(p, 'entry'), stop = num(p, 'stop'), tp = num(p, 'tp');
  const riskV = Math.abs(entry - stop), reward = Math.abs(tp - entry);
  if (!isFinite(entry) || !isFinite(stop) || !isFinite(tp) || riskV === 0) return J({ error: 'Required: entry, stop, tp (entry≠stop).' }, 400);
  const ratio = reward / riskV;
  return J({ entry, stop, tp, riskPerUnit: round(riskV, 2), rewardPerUnit: round(reward, 2), riskRewardRatio: round(ratio, 2), breakevenWinRatePct: round(riskV / (riskV + reward) * 100, 2) });
}
function calcTakeProfit(p) {
  const entry = num(p, 'entry'), lev = (isFinite(num(p, 'leverage')) && num(p, 'leverage') > 0) ? num(p, 'leverage') : 1, roe = num(p, 'roe');
  const side = (p.get('side') || 'long').toLowerCase();
  if (!isFinite(entry) || entry <= 0 || !isFinite(roe)) return J({ error: 'Required: entry (>0), roe. Optional: leverage, side.' }, 400);
  const long = side !== 'short';
  const exit = long ? entry * (1 + roe / 100 / lev) : entry * (1 - roe / 100 / lev);
  return J({ entry, leverage: lev, targetRoePct: roe, side: long ? 'long' : 'short', targetExitPrice: round(exit, 2), priceMovePct: round(roe / lev * (long ? 1 : -1), 2) });
}
// P1 mp-core (worker side): THE liquidation formula — every server fill path calls this one function.
// Client copies of the same formula are drift-guarded by build/check-formulas.js (verbatim literal asserts).
// ---- Competition period (owner 2026-07-24: 7d -> 14d) ----
// One canonical clock for EVERY leaderboard surface (boards, prizes, digest, profile week-stats, lb keys).
// Anchor = Monday 2026-07-20 00:00 UTC: the running week became the first 14-day season; existing lb rows
// are keyed by that same Monday timestamp so nothing orphaned. Boundaries stay Monday-aligned.
const LB_PERIOD = 14 * 86400000, LB_ANCHOR = Date.UTC(2026, 6, 20);
function lbPeriodStart(now) { now = +now || Date.now(); return LB_ANCHOR + Math.floor((now - LB_ANCHOR) / LB_PERIOD) * LB_PERIOD; }
function mpcLiq(entry, lev, mmr, long) { return long ? entry * (1 - (1 - mmr) / lev) : entry * (1 + (1 - mmr) / lev); }
function handleApi(url) {
  const p = url.searchParams;
  switch (url.pathname) {
    case '/api/liquidation': return calcLiquidation(p);
    case '/api/position-size': return calcPositionSize(p);
    case '/api/pnl': return calcPnl(p);
    case '/api/risk-reward': return calcRiskReward(p);
    case '/api/take-profit': return calcTakeProfit(p);
    default: return J({ error: 'Unknown endpoint. See https://marginpad.io/free-crypto-api/ (docs) or https://marginpad.io/api/openapi.json (spec).' }, 404);
  }
}

// ============================================================================
//  Public v1 API — one consistent, keyless, CORS-on, rate-limited data layer.
//  Envelope: { ok, data, error, ts }. Everything under /api/v1/*. Unknown v1
//  paths fall through to the collector proxy (recent/feed/clusters) unchanged.
//  Docs: /free-crypto-api/ · Spec: /api/openapi.json
// ============================================================================
const V1CORS = {
  'access-control-allow-origin': '*',
  'access-control-allow-methods': 'GET, POST, OPTIONS',
  'access-control-allow-headers': 'Content-Type, X-API-Key',
  'access-control-max-age': '86400',
  'content-type': 'application/json; charset=utf-8',
};
const V1_LIMIT = 60; // requests / minute / IP (generous, keyless)
const _v1rl = new Map(); // ip|minute -> count (per-isolate)
function v1Rate(ip) {
  const now = Date.now(), win = Math.floor(now / 60000), key = (ip || 'anon') + '|' + win;
  const n = (_v1rl.get(key) || 0) + 1; _v1rl.set(key, n);
  if (_v1rl.size > 8000) { for (const k of _v1rl.keys()) { if (!k.endsWith('|' + win)) _v1rl.delete(k); } }
  return { limited: n > V1_LIMIT, limit: V1_LIMIT, remaining: Math.max(0, V1_LIMIT - n), reset: (win + 1) * 60 };
}
function v1env(body, status, rlh, cache) {
  return new Response(JSON.stringify(body), { status: status || 200, headers: { ...V1CORS, ...(rlh || {}), 'cache-control': cache || 'no-store' } });
}
function v1ok(data, rlh, cache) { return v1env({ ok: true, data, ts: Date.now() }, 200, rlh, cache); }
function v1err(code, message, status, rlh) { return v1env({ ok: false, error: { code, message }, ts: Date.now() }, status || 400, rlh); }
function v1remap(url, pathname) { const u = new URL(url.toString()); u.pathname = pathname; return u; }
async function v1PriceResp(url) {
  const sym = String(url.searchParams.get('symbol') || url.searchParams.get('coin') || '').toUpperCase().replace(/[^A-Z0-9]/g, '');
  if (!sym) return new Response(JSON.stringify({ error: 'missing_symbol' }), { status: 400, headers: { 'content-type': 'application/json' } });
  const p = await fetchPrice(sym);
  return new Response(JSON.stringify(p ? { symbol: sym, ...p } : { error: 'not_found' }), { status: p ? 200 : 404, headers: { 'content-type': 'application/json', 'cache-control': 'public, max-age=5' } });
}
async function v1Unwrap(resp, rlh) {
  let data = null; try { data = await resp.clone().json(); } catch (e) {}
  if (data && data.error) {
    const code = String(data.error).toLowerCase().replace(/[^a-z0-9]+/g, '_').slice(0, 40) || 'error';
    const st = resp.status >= 400 ? resp.status : (code === 'not_found' || code === 'not_found_' ? 404 : 400);
    return v1err(code, typeof data.error === 'string' ? data.error : 'Request failed.', st, rlh);
  }
  const cc = resp.headers.get('cache-control') || 'public, max-age=15';
  return v1env({ ok: true, data, ts: Date.now() }, 200, rlh, cc);
}
async function handleV1(url, request, env, ctx) {
  if (request.method === 'OPTIONS') return new Response(null, { headers: V1CORS });
  const sub = url.pathname.slice('/api/v1/'.length).replace(/\/+$/, '');
  const ip = request.headers.get('cf-connecting-ip') || (request.headers.get('x-forwarded-for') || '').split(',')[0].trim();
  const rl = v1Rate(ip);
  const rlh = { 'x-ratelimit-limit': String(rl.limit), 'x-ratelimit-remaining': String(rl.remaining), 'x-ratelimit-reset': String(rl.reset) };
  if (rl.limited) return v1err('rate_limited', 'Rate limit exceeded: ' + V1_LIMIT + ' requests/minute per IP. Retry after X-RateLimit-Reset.', 429, rlh);
  if (sub === 'ping' || sub === 'status') return v1ok({ service: 'MarginPad Free Crypto API', version: '1.0', status: 'ok', keyless: true, cors: true, rateLimit: V1_LIMIT + '/min/IP', docs: 'https://marginpad.io/free-crypto-api/', openapi: 'https://marginpad.io/api/openapi.json', endpoints: ['price', 'prices', 'klines', 'symbols', 'screener', 'funding', 'open-interest', 'long-short', 'liquidations', 'calendar', 'fear-greed', 'coins', 'global', 'trending', 'defi', 'calc/liquidation', 'calc/position-size', 'calc/pnl', 'calc/risk-reward', 'calc/take-profit'] }, rlh);
  const M = {
    'price': () => v1PriceResp(url),
    'prices': () => handlePrices(env, ctx),
    'klines': () => handleKlines(v1remap(url, '/api/klines')),
    'symbols': () => handleSymbols(),
    'screener': () => handleScreener(env, false),
    'funding': () => handleCgFunding(v1remap(url, '/api/cg/funding'), env),
    'open-interest': () => handleCgOpenInterest(v1remap(url, '/api/cg/openinterest'), env),
    'long-short': () => handleCgLongShort(v1remap(url, '/api/cg/longshort'), env),
    'liquidations': () => handleCgLiquidations(v1remap(url, '/api/cg/liquidations'), env),
    'calendar': () => handleCalendar(request, env),
    'fear-greed': () => handleFng(env),
    'coins': () => handleGeckoMarkets(v1remap(url, '/api/gecko/markets'), env),
    'global': () => handleGeckoGlobal(env),
    'trending': () => handleGeckoTrending(env),
    'defi': () => handleDefiOverview(env),
    'calc/liquidation': () => handleApi(v1remap(url, '/api/liquidation')),
    'calc/position-size': () => handleApi(v1remap(url, '/api/position-size')),
    'calc/pnl': () => handleApi(v1remap(url, '/api/pnl')),
    'calc/risk-reward': () => handleApi(v1remap(url, '/api/risk-reward')),
    'calc/take-profit': () => handleApi(v1remap(url, '/api/take-profit')),
  };
  const fn = M[sub];
  if (!fn) return handleCollectorProxy(url, request, env); // unknown /api/v1/* → collector proxy (recent/feed/clusters/…): never break existing consumers
  let resp; try { resp = await fn(); } catch (e) { return v1err('upstream_error', 'Upstream data source failed. Please retry shortly.', 502, rlh); }
  return v1Unwrap(resp, rlh);
}
