      '/api/bot/v1/account': { get: { tags: ['Paper trading'], summary: 'Paper account', description: 'Simulated account balance and stats. Auth: X-API-Key.', security: [{ ApiKeyAuth: [] }], responses: { '200': { description: 'ok' } } } },
