  try {
    const unlocks = await fetchTokenUnlocks(env);
    unlocks.forEach(e => { if (e.ts >= from && e.ts <= to) events.push({ ...e, allday: true }); });
  } catch (e) {}
  // Owner-added one-off events (conferences, upgrades, listings…) — KV cal:extra, edited from ops Settings.
  try {
    const extra = JSON.parse(await env.STATS.get('cal:extra') || '[]') || [];
    extra.forEach(x => { const p = parse(String(x.d || '')); if (!isFinite(p.y)) return;
      const ts = Date.UTC(p.y, p.mo, p.d, 12, 0); if (!isFinite(ts) || ts < from || ts > to) return;
      events.push({ ts, type: x.type || 'crypto', title: String(x.title || 'Event').slice(0, 90), desc: String(x.desc || '').slice(0, 240), impact: Math.min(3, Math.max(1, +x.impact || 2)), allday: true }); });
  } catch (e) {}
