        const kk = kindOf(ev.title); const ts = Date.parse(ev.date); if (!isFinite(ts)) return;
        const kind = kk ? kk[0] : 'macro', title = kk ? kk[1] : ('US ' + String(ev.title).slice(0, 70)), impact = kk ? kk[2] : (ev.impact === 'High' ? 2 : 1);
        const key = new Date(ts).toISOString().slice(0, 10) + ':' + kind + ':' + title;
