                  await env.STATS.put('csig:live:' + sym, JSON.stringify({ sigDir: lDir, entry: e, risk, tp1, tp2, sl, phase: 0, peakHi: e, peakLo: e, cool: now + liveCool, ts: now, done: false, msgId: mid, sigId, firedBar: curBar }));
