    let posts24 = 0; try { const r = await env.COMM.get(env.COMM.idFromName('main')).fetch(new Request('https://do/feed?sort=new')); const d = await r.json(); posts24 = ((d && d.posts) || []).filter(x => x.ts > Date.now() - 86400000).length; } catch (e) {}
    const arrow = (a, b) => b > 0 ? (a >= b ? ' ▲' + Math.round((a - b) / b * 100) + '%' : ' ▼' + Math.round((b - a) / b * 100) + '%') : '';
    const pend = (rw.pending || []).length, pendUsd = (rw.pending || []).reduce((t, w) => t + (+w.amountUsd || 0), 0);
