  function jmActsInfo(acts){
    var groups={},ord=[],junk=0,gold=0,mn=0;
    for(var i=0;i<acts.length;i++){var c2=jmClass(acts[i]);
      if(!c2)continue;
      if(c2.junk){junk++;continue;}
      mn++;if(c2.kind==='gold')gold++;
      var k2=c2.txt;
      if(!groups[k2]){groups[k2]={n:0,kind:c2.kind,pr:c2.pr,first:acts[i].ts,last:acts[i].ts};ord.push(k2);}
      var G=groups[k2];G.n++;if(acts[i].ts<G.first)G.first=acts[i].ts;if(acts[i].ts>G.last)G.last=acts[i].ts;}
    ord.sort(function(a,b){return groups[a].pr-groups[b].pr||groups[b].n-groups[a].n;});
    return {groups:groups,ord:ord,junk:junk,gold:gold,mn:mn};}
