    var entryLbl=(JM.mode==='user'||g._hdr==='sess')?new Date(g.items[0]?g.items[0].ts:g.last).toLocaleTimeString().slice(0,5):('via '+String(srcName(g.s)).split(' ')[0].slice(0,12));
