    +'<div class="ovz-h" style="margin-top:14px">Top pairs</div>'
    +coins.slice(0,5).map(function(sy){var b=by[sy];return '<div style="display:flex;gap:8px;align-items:center;font-family:Consolas,monospace;font-size:11px;padding:4px 0"><span class="ovz-dot" style="width:16px;height:16px;font-size:7px;background:'+ovzCoinCol(sy)+'">'+esc(sy.slice(0,2))+'</span><span style="flex:1;color:#dbe4f5">'+esc(sy)+'-PERP</span><b style="color:#c2f64a">'+ovzMoney(b.m)+'</b><span style="color:#5c6b84;width:44px;text-align:right">'+b.n+' pos</span></div>';}).join('');
