function loadPremium(){var el=document.getElementById('premDesk');if(!el)return;fetch('/api/admin/premdesk').then(function(r){return r.json();}).catch(function(){return null;}).then(function(d){d=d||{users:[],open:[],closed:[]};var syms=[],seen={};(d.open||[]).forEach(function(t){if(t.sym&&!seen[t.sym]){seen[t.sym]=1;syms.push(t.sym);}});/* per-symbol price: premium traders hold alts (TAO/EUL/HYPE/…) the 8-major /api/prices bulk feed never covers, and its shape is {pairs:[…]} not {prices:[…]} — that combo left Unrealized at $0. Fetch one price per distinct open symbol (edge-cached 5s) keyed by the bare sym, matching unreal(t)'s px[t.sym]. */Promise.all(syms.map(function(sy){return fetch('/api/price?symbol='+encodeURIComponent(sy)).then(function(r){return r.ok?r.json():null;}).catch(function(){return null;}).then(function(j){return {sy:sy,p:(j&&+((j.price!=null?j.price:j.p!=null?j.p:j.last)))||0};});})).then(function(arr){var px={};arr.forEach(function(x){if(x.p>0)px[x.sy]=x.p;});renderPremium(el,d,px);});});}
function renderPremium(el,d,px){
  var _e=function(s){return String(s==null?'':s).replace(/[<>&]/g,function(m){return{'<':'&lt;','>':'&gt;','&':'&amp;'}[m];});};
  var _m=function(v){v=+v||0;var s=v<0?'-':'',a=Math.abs(v);var t=a>=1e9?(a/1e9).toFixed(2)+'B':a>=1e6?(a/1e6).toFixed(2)+'M':a>=1e3?(a/1e3).toFixed(1)+'K':a.toFixed(2);return s+'$'+t;};
  var _fl=function(cc){return /^[A-Z]{2}$/.test(cc)?String.fromCodePoint(127397+cc.charCodeAt(0),127397+cc.charCodeAt(1)):'';};
  var _ago=function(t){if(!t)return '—';var s=Math.round((Date.now()-t)/1000);return s<60?s+'s':s<3600?Math.floor(s/60)+'m':s<86400?Math.floor(s/3600)+'h':Math.floor(s/86400)+'d';};
  var users=d.users||[],open=d.open||[],closed=d.closed||[];
  function unreal(t){var p=px[t.sym];if(!(p>0)||!(t.qty>0))return null;var dir=t.side!=='short'?1:-1;var pl=t.qty*(p-t.entry)*dir;if(t.margin>0&&pl<-t.margin*0.99)pl=-t.margin*0.99;return pl;}
  var uUn={};open.forEach(function(t){var u=unreal(t);if(u!=null)uUn[t.uid]=(uUn[t.uid]||0)+u;});
  var tBal=0,tEarned=0,tReal=0,tUn=0;users.forEach(function(u){tBal+=u.balance||0;tEarned+=u.earned||0;tReal+=u.realized||0;tUn+=uUn[u.uid]||0;});
  function card(v,l,col){return '<div class="card"><div class="cv"'+(col?' style="color:'+col+'"':'')+'>'+v+'</div><div class="cl">'+l+'</div></div>';}
  var html='<div class="cards" style="margin-bottom:16px">'+card(users.length,'Premium members')+card(open.length,'Open positions')+card((tReal>=0?'+':'')+_m(tReal),'Realized P&L',tReal>=0?'#2ebd85':'#ff6258')+card((tUn>=0?'+':'')+_m(tUn),'Unrealized (open)',tUn>=0?'#2ebd85':'#ff6258')+card(_m(tBal),'Reward balance','#c2f64a')+card(_m(tEarned),'Total earned')+'</div>';
  users.sort(function(a,b){return ((b.realized||0)+(uUn[b.uid]||0))-((a.realized||0)+(uUn[a.uid]||0));});
  html+='<h2 style="margin-top:4px">Members <span>click a row for the full money breakdown (where it came from)</span></h2><div style="overflow-x:auto"><table class="pf-t"><thead><tr><th>Member</th><th>Balance</th><th>Earned</th><th>Claims</th><th>Realized</th><th>Unreal.</th><th>Open</th><th>W/L</th><th>Seen</th></tr></thead><tbody>';
  html+=users.map(function(u){var un=uUn[u.uid];var tag=u.founder?' <span style="color:#ffd75a;font-size:9px;font-weight:800">FOUNDER</span>':(u.premUntil>4e12?'':(u.premUntil>Date.now()?' <span style="color:#8fa3c4;font-size:9px">'+new Date(u.premUntil).toISOString().slice(0,10)+'</span>':''));return '<tr data-acct="u:'+_e(u.uid)+'" style="cursor:pointer"><td style="white-space:nowrap">'+_fl(u.cc)+' <b>'+(u.username?'@'+_e(u.username):_e(u.email||u.uid))+'</b>'+tag+'</td><td style="color:#c2f64a">'+_m(u.balance)+'</td><td>'+_m(u.earned)+'</td><td>'+(u.claims||0)+'</td><td style="color:'+((u.realized||0)>=0?'#2ebd85':'#ff6258')+'">'+((u.realized||0)>=0?'+':'')+_m(u.realized)+'</td><td style="color:'+((un||0)>=0?'#2ebd85':'#ff6258')+'">'+(un==null?'—':((un>=0?'+':'')+_m(un)))+'</td><td>'+(u.openN||0)+'</td><td>'+(u.wins||0)+'/'+(u.losses||0)+'</td><td>'+_ago(u.lastSeen)+'</td></tr>';}).join('')+'</tbody></table></div>';
  html+='<h2 style="margin-top:20px">Premium open tickets <span>'+open.length+' live · who holds what</span></h2>';
  html+=open.length?'<div style="overflow-x:auto"><table class="pf-t"><thead><tr><th>Trader</th><th>Pair</th><th>Side</th><th>Lev</th><th>Margin</th><th>Entry</th><th>Liq</th><th>Live P&L</th><th>Age</th></tr></thead><tbody>'+open.map(function(t){var un=unreal(t);return '<tr><td style="white-space:nowrap"><b>@'+_e(t.who)+'</b>'+(t.bal?' <span style="color:#f0c35a;font-size:9px;font-weight:800">BAL</span>':'')+'</td><td>'+_e(t.sym)+'</td><td style="color:'+(t.side!=='short'?'#2ebd85':'#ff6258')+'">'+(t.side!=='short'?'LONG':'SHORT')+'</td><td>'+t.lev+'×</td><td>'+_m(t.margin)+'</td><td>'+(+t.entry).toLocaleString()+'</td><td>'+(+t.liq).toLocaleString()+'</td><td style="color:'+((un||0)>=0?'#2ebd85':'#ff6258')+'">'+(un==null?'—':((un>=0?'+':'')+_m(un)))+'</td><td>'+_ago(t.ts)+'</td></tr>';}).join('')+'</tbody></table></div>':'<div class="empty">no open premium positions</div>';
  html+='<h2 style="margin-top:20px">Premium closed tickets <span>recent</span></h2>';
  html+=closed.length?'<div style="overflow-x:auto"><table class="pf-t"><thead><tr><th>Trader</th><th>Pair</th><th>Side</th><th>Lev</th><th>Margin</th><th>P&L</th><th>Result</th><th>When</th></tr></thead><tbody>'+closed.map(function(t){return '<tr><td style="white-space:nowrap"><b>@'+_e(t.who)+'</b>'+(t.bal?' <span style="color:#f0c35a;font-size:9px;font-weight:800">BAL</span>':'')+'</td><td>'+_e(t.sym)+'</td><td style="color:'+(t.side!=='short'?'#2ebd85':'#ff6258')+'">'+(t.side!=='short'?'LONG':'SHORT')+'</td><td>'+t.lev+'×</td><td>'+_m(t.margin)+'</td><td style="color:'+(t.pnl>=0?'#2ebd85':'#ff6258')+'">'+(t.pnl>=0?'+':'')+_m(t.pnl)+'</td><td>'+(t.liq?'<span style="color:#b48cff">LIQ</span>':(t.pnl>=0?'<span style="color:#2ebd85">WIN</span>':'<span style="color:#ff8a80">LOSS</span>'))+'</td><td>'+_ago(t.ts)+'</td></tr>';}).join('')+'</tbody></table></div>':'<div class="empty">no closed premium trades yet</div>';
  el.innerHTML=html;
  Array.prototype.forEach.call(el.querySelectorAll('[data-acct]'),function(r){r.addEventListener('click',function(){try{openAcct(r.getAttribute('data-acct'));}catch(e){}});});
}
