    if(!d)return;
    var by={};(d.evByDay||[]).forEach(function(x){var dy=String(x.d).slice(0,10);if(!by[dy])by[dy]={};by[dy][String(x.ty)]=(by[dy][String(x.ty)]||0)+(+x.n);});
