      +card(N(t9.ex)+' <small class="cvsub" style="color:#ffd75a">'+pcv(t9.ex,t9.uv)+'% of uv</small>','exchange clicks today')
      +card(N(t9.signup)+' <small class="cvsub">'+N(t9.claim)+' claims</small>','signups today');
