    var ex=document.getElementById('rvEx');
    if(ex)ex.innerHTML=byEx.length?byEx.map(function(x){return '<div class="row"><div class="lbl"><span style="display:inline-block;width:9px;height:9px;border-radius:3px;background:'+addrColor(x.ex)+';margin-right:7px;vertical-align:-1px"></span>'+esc(x.ex)+'</div><div class="track"><div class="fill" style="width:'+Math.max(4,x.n/byEx[0].n*100)+'%"></div></div><div class="cnt">'+N(x.n)+' <small style="color:#7f8893">~$'+(x.n*usd).toFixed(0)+'</small></div></div>';}).join(''):'<div class="empty">no clicks recorded</div>';
    var pg=document.getElementById('rvPage');
