    +(d.sessDo?(function(){var age=d.sessDo.ts?Math.round((Date.now()-d.sessDo.ts)/60000):null;var stale=(age!=null&&age>20)?' <span style="color:#ff6258">· stale '+age+'m (cron?)</span>':'';
      return card('<span style="color:#38bdf8">'+(d.sessDo.doReachRate!=null?d.sessDo.doReachRate:'—')+'%</span>','Session&rarr;DO reach <small class="cvsub">'+N(d.sessDo.total||0)+' · '+(d.sessDo.win||'')+' · lower = KV caching'+stale+'</small>')
        +card((d.sessDo.errRate||0)===0?'<span style="color:#2ebd85">0%</span>':'<span style="color:'+((d.sessDo.errRate>=5)?'#ff6258':'#ffb020')+'">'+d.sessDo.errRate+'%</span>','Session DO errRate <small class="cvsub">kill switch if high</small>')
        +(d.sessDo.p95==null?card('<span style="opacity:.5">—</span>','Session DO p95 <small class="cvsub">no data</small>'):card(v(d.sessDo.p95,'ms',150,400),'Session DO p95 <small class="cvsub">round-trip</small>'));})():'')
    +(d.cronErrs?(d.cronErrs.length?card('<span style="color:#ff6258">'+N(d.cronErrs.reduce(function(s,r){return s+(r.n||0);},0))+'</span>','Cron failures 24h <small class="cvsub">'+d.cronErrs.map(function(r){return r.task+'&times;'+N(r.n);}).join(' · ')+'</small>'):card('<span style="color:#2ebd85">0</span>','Cron failures 24h <small class="cvsub">all */10 tasks ran clean</small>')):'');
