var gsIn=document.getElementById('gsIn'),gsDrop=document.getElementById('gsDrop'),gsT=null,gsSeq=0;
function gsHide(){if(gsDrop){gsDrop.hidden=true;}}
function gsRender(d){
  if(!gsDrop)return;var h='';
  if(d.users&&d.users.length){h+='<div class="gsr-h">Users</div>'+d.users.map(function(u){var nm=u.username||u.email.split('@')[0];return '<div class="gsr-r" data-go="user" data-v="'+esc(u.email)+'">'+flag(u.cc)+' <b>'+esc(nm)+'</b> <span style="color:#7f8893;font-size:11.5px">'+esc(u.email)+'</span><span class="m">'+(u.pv||0)+' pv · '+(u.trades||0)+' tr</span></div>';}).join('');}
  if(d.accounts&&d.accounts.length){h+='<div class="gsr-h">Faucet accounts</div>'+d.accounts.map(function(a){return '<div class="gsr-r" data-go="acct" data-v="'+esc(a.address)+'"><b class="mono" style="font-size:12px'+(a.banned?';text-decoration:line-through':'')+'">'+esc(a.address.length>26?a.address.slice(0,12)+'…'+a.address.slice(-8):a.address)+'</b><span class="m">$'+(+a.balanceUsd).toFixed(2)+' · '+a.claims+'×'+(a.banned?' · BANNED':'')+'</span></div>';}).join('');}
  if(d.posts&&d.posts.length){h+='<div class="gsr-h">Community posts</div>'+d.posts.map(function(x){return '<div class="gsr-r" data-go="post" data-v="'+esc(x.id)+'"><b style="overflow:hidden;text-overflow:ellipsis;white-space:nowrap">'+esc(x.title)+'</b><span class="m">'+esc(x.author)+' · 💬'+(x.ncom||0)+'</span></div>';}).join('');}
  gsDrop.innerHTML=h||'<div class="gsr-empty">Nothing found.</div>';
  gsDrop.hidden=false;
}
if(gsIn){
  gsIn.addEventListener('input',function(){
    clearTimeout(gsT);var q=(gsIn.value||'').trim();
    if(q.length<2){gsHide();return;}
    gsT=setTimeout(function(){
      var seq=++gsSeq;
      fetch('/api/admin/search?q='+encodeURIComponent(q)+'&_='+Date.now()).then(function(r){return r.json();}).then(function(d){if(seq===gsSeq)gsRender(d||{});}).catch(function(){});
    },280);
  });
  gsIn.addEventListener('keydown',function(e){if(e.key==='Escape'){gsHide();gsIn.blur();}if(e.key==='Enter'){var f=gsDrop&&!gsDrop.hidden&&gsDrop.querySelector('.gsr-r');if(f)f.click();}});
  if(gsDrop)gsDrop.addEventListener('click',function(e){
    var r=e.target.closest('.gsr-r');if(!r)return;
    var go=r.getAttribute('data-go'),v=r.getAttribute('data-v');
    gsHide();gsIn.value='';
    if(go==='user')openUser(v);
    else if(go==='acct'){show('rewards');openAcct(v);}
    else if(go==='post')window.open('https://marginpad.io/community/p/'+v,'_blank','noopener');
  });
  document.addEventListener('pointerdown',function(e){if(gsDrop&&!gsDrop.hidden&&!e.target.closest('.gsr'))gsHide();});
  document.addEventListener('keydown',function(e){
    if(e.key!=='/'||e.ctrlKey||e.metaKey||e.altKey)return;
    var a=document.activeElement;if(a&&(a.tagName==='INPUT'||a.tagName==='TEXTAREA'||a.tagName==='SELECT'))return;
    e.preventDefault();gsIn.focus();gsIn.select();
  });
}

