    let log = []; try { log = JSON.parse(await env.STATS.get('evlog') || '[]'); } catch (e) {}
    log.unshift({ t: 'bot', e: cmd.slice(0, 24), cc: '', v: 'srv', u, p: '', d: 'Telegram', ts: Date.now() });
