// Profile-card frame cosmetics: what a user owns (level tiers unlock as you rank up; neon/aurora = premium; founder = founder)
function frameOwned(fr, xp, premium, founder) {
  if (!fr || fr === 'default') return true;
  if (fr === 'neon' || fr === 'aurora') return !!premium;
  if (fr === 'founder') return !!founder;
  const lv = XP_LEVELS.find(l => l.k === fr); if (lv) return (+xp || 0) >= lv.min;
  return false;
}
function framesFor(xp, premium, founder) {
  const owned = ['default'];
  for (const l of XP_LEVELS) if (l.k !== 'bronze' && (+xp || 0) >= l.min) owned.push(l.k);
  if (premium) { owned.push('neon'); owned.push('aurora'); }
  if (founder) owned.push('founder');
  return owned;
}
