  commands.sort((a, b) => b[1] - a[1]);
  const gc = async k => { try { const r = await env.STATS.getWithMetadata(k); return (r && r.metadata && r.metadata.c) || (r && r.value ? +r.value : 0) || 0; } catch (e) { return 0; } };
