  const prize = '$' + (Math.round(info.prizeUsd * 100) / 100).toFixed(2);
  const esc = x => String(x == null ? '' : x).replace(/[<>&]/g, m => ({ '<': '&lt;', '>': '&gt;', '&': '&amp;' }[m]));
