    try { const rk = 'nudge:' + uid; const last = +(await env.STATS.get(rk)) || 0; if (Date.now() - last < 3000) return jt({ ok: true, throttled: true }); const putP = env.STATS.put(rk, String(Date.now()), { expirationTtl: 60 }); if (ctx) ctx.waitUntil(putP.catch(() => {})); else await putP; } catch (e) {}
    const seed = await usersDO(env, '/botpositions', { uid, prices: {} });
    const open = seed && seed.positions ? seed.positions.filter(p => p.status === 'open' && ['srv', 'bot'].indexOf(String(p.id).slice(0, 3)) >= 0) : [];
