    try { s.exec('CREATE INDEX IF NOT EXISTS ps_uid ON psubs(uid)'); } catch (e) {}
    try { s.exec('CREATE INDEX IF NOT EXISTS uev_user ON uevents(user_id, ts)'); } catch (e) {}
    try { s.exec('CREATE INDEX IF NOT EXISTS ucl_user ON uclicks(user_id, ts)'); } catch (e) {}
    try { s.exec('CREATE UNIQUE INDEX IF NOT EXISTS uname_uniq ON users(username) WHERE username IS NOT NULL'); } catch (e) {} // enforce unique usernames at the DB level too
    s.exec('CREATE TABLE IF NOT EXISTS aiuse(k TEXT PRIMARY KEY, n INTEGER NOT NULL DEFAULT 0)'); // atomic per-user daily "Ask AI" counter (k = uid|day) — KV was racy and over-spent the paid LLM quota
    s.exec('CREATE TABLE IF NOT EXISTS botkeys(k TEXT PRIMARY KEY, uid TEXT UNIQUE, created INTEGER, calls INTEGER DEFAULT 0, mn TEXT, mint INTEGER DEFAULT 0)'); // bot-API keys (one per account) + per-minute rate window
    s.exec('CREATE TABLE IF NOT EXISTS botpos(id TEXT PRIMARY KEY, uid TEXT, json TEXT, status TEXT, ts INTEGER)'); // server-side paper positions opened via the bot API
    s.exec('CREATE TABLE IF NOT EXISTS botuse(uid TEXT, day TEXT, ep TEXT, n INTEGER DEFAULT 0, last INTEGER, PRIMARY KEY(uid,day,ep))');
    s.exec('CREATE TABLE IF NOT EXISTS missions(user_id TEXT, day TEXT, mid TEXT, ts INTEGER, PRIMARY KEY(user_id,day,mid))');
    s.exec('CREATE TABLE IF NOT EXISTS tradeev(id INTEGER PRIMARY KEY AUTOINCREMENT, user_id TEXT, ts INTEGER, kind TEXT, sym TEXT, side TEXT, lev REAL, margin REAL, pnl REAL, roe REAL, liq INTEGER DEFAULT 0)'); // persistent open/close trade events (diffed on journal sync — real pnl on closes)
    s.exec('CREATE INDEX IF NOT EXISTS tradeev_ts ON tradeev(ts)'); // claimed daily missions (verification runs against uevents) // per-user per-endpoint daily API usage (the ops API tab reads this)
    try { s.exec('CREATE INDEX IF NOT EXISTS tradeev_uid ON tradeev(user_id, ts)'); } catch (e) {} // for per-user window stats (duels)
    try { s.exec('ALTER TABLE tradeev ADD COLUMN via TEXT'); } catch (e) {} // B3: executor attribution — client / site / bot / sweep / cron / sltp
    s.exec('CREATE TABLE IF NOT EXISTS duels(id TEXT PRIMARY KEY, a_uid TEXT, b_uid TEXT, a_name TEXT, b_name TEXT, metric TEXT, created INTEGER, start_ts INTEGER, end_ts INTEGER, status TEXT, winner TEXT, a_score REAL, b_score REAL, settled INTEGER DEFAULT 0)'); // friend duels (stat challenges). status: pending/active/declined/done/expired. metric: roe/wr/win/pnl/survival/streak/sniper
    ['dur INTEGER', 'stake INTEGER', 'escrowed INTEGER', 'sym TEXT', 'rules TEXT'].forEach(c => { try { s.exec('ALTER TABLE duels ADD COLUMN ' + c); } catch (e) {} }); // Duels 2.0: variable duration, XP wager, escrow state, locked symbol, extra rules json
    try { s.exec('CREATE INDEX IF NOT EXISTS bp_uid ON botpos(uid, ts)'); } catch (e) {}
