// mulberry32 — tiny deterministic PRNG so a day's missions are STABLE within that day (claims re-derive the set)
// but well-shuffled and different day-to-day (feels random). Seeded from the UTC date.
function _missionRng(seed) { let s = (seed ^ 0x9e3779b9) >>> 0; return function () { s = (s + 0x6d2b79f5) >>> 0; let t = s; t = Math.imul(t ^ (t >>> 15), t | 1); t ^= t + Math.imul(t ^ (t >>> 7), t | 61); return ((t ^ (t >>> 14)) >>> 0) / 4294967296; }; }
function missionsForDay(day, opts) { // daily set: 1 trade mission + the Telegram-group mission + 6 category-capped picks, seeded by the date.
  // CAPS fix the "3 academy missions in one day" problem: a plain shuffle could stack one category; now each day is a designed mix.
  opts = opts || {};
  const seed = parseInt(String(day).replace(/-/g, ''), 10) || 0;
  const rnd = _missionRng(seed);
  const tradeM = MISSION_POOL[rnd() < 0.5 ? 0 : 1]; // trade1 or trade3 (random per day)
  const promoM = MISSION_POOL.find(m => m.mid === 'tggroup'); // Telegram-group growth push — in EVERY day's set
  const rest = MISSION_POOL.filter(m => m.cat !== 'core' && m.mid !== 'tggroup');
  for (let i = rest.length - 1; i > 0; i--) { const j = Math.floor(rnd() * (i + 1)); const t = rest[i]; rest[i] = rest[j]; rest[j] = t; } // Fisher–Yates
  const skip = opts.academyDone ? (m => m.vt === 'academy') : (() => false); // finished-Academy users can't complete lesson missions
  const CAPS = { academy: 1, chat: 1, community: 1, social: 2, trade: 2, market: 3 }; // per-day category quotas
  const used = {}; const pick = [];
  for (let i = 0; i < rest.length && pick.length < 6; i++) {
    const m = rest[i]; if (skip(m)) continue;
    const c = m.cat || 'market'; if ((used[c] || 0) >= (CAPS[c] != null ? CAPS[c] : 2)) continue;
    used[c] = (used[c] || 0) + 1; pick.push(m);
  }
  for (let i = 0; i < rest.length && pick.length < 6; i++) { const m = rest[i]; if (skip(m) || pick.indexOf(m) >= 0) continue; pick.push(m); } // cap-relaxed fallback — never under-fill the day
  return [tradeM, promoM, ...pick].filter(Boolean);
}
// ---------- Academy: Duolingo-style lesson path (content lives on /academy/; server = progress + XP) ----------
const ACAD_COURSES = { basics: ['b1','b2','b3','b4','b5','b6','b7','b8','b9'], candles: ['c1','c2','c3','c4','c5','c6','c7','c8'], leverage: ['l1','l2','l3','l4','l5','l6','l7','l8','l9','l10','l11','l12'], risk: ['r1','r2','r3','r4','r5','r6','r7','r8','r9','r10','r11','r12'], market: ['m1','m2','m3','m4','m5','m6','m7','m8','m9','m10','m11','m12'], structure: ['a1','a2','a3','a4','a5','a6','a7','a8'], systems: ['s1','s2','s3','s4','s5','s6','s7'], going: ['g1','g2','g3','g4','g5'], stories: ['st1','st2','st3','st4','st5','st6','st7','st8'], psychology: ['py1','py2','py3','py4','py5','py6','py7','py8'], mastery: ['mm1','mm2','mm3','mm4','mm5','mm6','mm7'] }; // MUST match dist/academy #acadData course/lesson ids (9 courses, 81 lessons; 'stories' is free:true = always unlocked, outside the lock chain)
async function handleAcademy(url, request, env) {
  const jh = { 'content-type': 'application/json; charset=utf-8', 'cache-control': 'no-store', ...CORS };
  const jr = (o, st) => new Response(JSON.stringify(o), { status: st || 200, headers: jh });
  let uid = '', xp = 0, level = null;
  const tok = getCookie(request, SESS_COOKIE);
  if (tok && env.USERS) { const su = await sessionUser(env, tok); if (su && su.id) { uid = su.id; xp = su.xp || 0; level = su.level || null; } }
  const adminUid = url.searchParams.get('uid'); // owner preview/testing: act as a user (admin cookie only, same pattern as missions)
  if (adminUid && (await adminCookieOk(request, env))) uid = adminUid;
  const stub = env.USERS ? env.USERS.get(env.USERS.idFromName('main')) : null;
  if (request.method === 'GET') {
    if (!uid || !stub) return jr({ signedIn: false, done: [] });
    let done = []; try { const r = await stub.fetch(new Request('https://do/academy/state?uid=' + encodeURIComponent(uid))); done = ((await r.json()) || {}).done || []; } catch (e) {}
    return jr({ signedIn: true, done, xp, level });
  }
  if (request.method === 'POST') {
    if (!uid || !stub) return jr({ error: 'login_required' }, 401);
    let b = {}; try { b = await request.json(); } catch (e) {}
    const lesson = String(b.lesson || '').replace(/[^a-z0-9]/gi, '').slice(0, 12);
    let course = null; for (const c in ACAD_COURSES) if (ACAD_COURSES[c].indexOf(lesson) >= 0) { course = c; break; }
    if (!course) return jr({ error: 'bad_lesson' }, 400);
    try {
      const r = await stub.fetch(new Request('https://do/academy/complete', { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ uid, lesson, course, courseLessons: ACAD_COURSES[course] }) }));
      const rd = await r.json();
      if (rd && !rd.error) { try { await evPush(env, request, 'academy', lesson, '/academy/'); } catch (e) {} }
      return jr(rd);
    } catch (e) { return jr({ error: 'busy' }, 503); }
  }
  return jr({ error: 'method' }, 405);
}
async function handleMissions(url, request, env) {
  const jh = { 'content-type': 'application/json; charset=utf-8', 'cache-control': 'no-store', ...CORS };
  const jr = (o, st) => new Response(JSON.stringify(o), { status: st || 200, headers: jh });
  const cfg = await rewardCfg(env);
  const enabled = cfg.raw ? cfg.raw.missionsEnabled !== false : true;
  const day = new Date().toISOString().slice(0, 10);
  const dayStart = new Date(day).getTime();
  let uid = '';
  const tok = getCookie(request, SESS_COOKIE);
  if (tok && env.USERS) { const su = await sessionUser(env, tok); if (su && su.id) uid = su.id; }
  const adminUid = url.searchParams.get('uid'); // owner preview/testing: act as a user (admin cookie only)
  if (adminUid && (await adminCookieOk(request, env))) uid = adminUid;
  if (!enabled) return jr({ enabled: false, missions: [] });
  if (!uid) return jr({ enabled: true, signedIn: false, missions: [], day }); // missions are NOT available to logged-out users — don't expose the list, just prompt sign-in on the client
  let defs = missionsForDay(day);
  // Owner rule: a user who FINISHED the whole Academy must not get lesson-completion missions (impossible for them) →
  // swap them out for the next mission. Only fetch the completion count on days those missions actually appear.
  if (defs.some(m => m.vt === 'academy')) {
    let academyDone = false;
    try { const ar = await env.USERS.get(env.USERS.idFromName('main')).fetch(new Request('https://do/academy/state?uid=' + encodeURIComponent(uid))); const done = ((await ar.json()) || {}).done || []; academyDone = done.filter(x => !String(x).startsWith('course:')).length >= 96; } catch (e) {}
    if (academyDone) defs = missionsForDay(day, { academyDone: true });
  }
  const evDefs = defs.filter(m => m.vt !== 'comm').map(m => ({ mid: m.mid, vt: m.vt, va: m.va, n: m.n }));
  let st = { done: {}, claimed: {} };
  try { const r = await env.USERS.get(env.USERS.idFromName('main')).fetch(new Request('https://do/missions/state', { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ uid, day, dayStart, defs: evDefs }) })); st = await r.json(); } catch (e) {}
  for (const m of defs) if (m.vt === 'comm') {
    try { const r = await env.COMM.get(env.COMM.idFromName('main')).fetch(new Request('https://do/activity', { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ uid, fromTs: dayStart }) })); const d = await r.json(); st.done[m.mid] = ((d.posts || 0) + (d.comments || 0)) >= (m.n || 1); } catch (e) { st.done[m.mid] = false; }
  }
  const missions = defs.map(m => ({ mid: m.mid, title: m.title, desc: m.desc, cents: m.cents, url: m.url || undefined, done: !!(st.done && st.done[m.mid]), claimed: !!(st.claimed && st.claimed[m.mid]) }));
  if (request.method === 'POST') {
    let b = {}; try { b = await request.json(); } catch (e) {}
    const mid = String(b.mid || '');
    const m = defs.find(x => x.mid === mid);
    if (!m) return jr({ error: 'bad_mission' }, 400);
    if (!st.done[mid]) return jr({ error: 'not_done' }, 400);
    if (st.claimed[mid]) return jr({ error: 'already_claimed' }, 400);
    let fresh = false;
    try { const r = await env.USERS.get(env.USERS.idFromName('main')).fetch(new Request('https://do/missions/claim', { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ uid, day, mid }) })); const d = await r.json(); fresh = !!d.fresh; } catch (e) { return jr({ error: 'transient' }, 503); }
    if (!fresh) return jr({ error: 'already_claimed' }, 400);
    let balanceUsd = null;
    try { const r = await env.REWARDS.get(env.REWARDS.idFromName('ledger')).fetch(new Request('https://do/mission', { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ acct: 'u:' + uid, cents: m.cents, mid }) })); const d = await r.json(); if (d.error) return jr({ error: d.error }, 403); balanceUsd = d.balanceUsd; } catch (e) {}
    try { await evPush(env, request, 'mission', mid + ' +$' + (m.cents / 100).toFixed(2), '/rewards/'); } catch (e) {}
    const upd = missions.map(x => x.mid === mid ? { ...x, claimed: true } : x);
    return jr({ ok: true, credited: m.cents / 100, balanceUsd, missions: upd, day });
  }
  return jr({ enabled: true, signedIn: true, missions, day, resetInMs: (dayStart + 86400000) - Date.now() });
}
// ---------- IndexNow (Bing/Yandex/Seznam/Naver instant indexing) ----------
const INDEXNOW_KEY = '9f3c7e21b84d4a6fae0c5d2178b6e093'; // public by protocol design — the key file at /<key>.txt proves ownership
async function indexNowPing(urls) {
  if (!urls || !urls.length) return;
  try {
    await fetch('https://api.indexnow.org/indexnow', {
      method: 'POST', headers: { 'content-type': 'application/json; charset=utf-8' },
      body: JSON.stringify({ host: 'marginpad.io', key: INDEXNOW_KEY, keyLocation: 'https://marginpad.io/' + INDEXNOW_KEY + '.txt', urlList: urls.slice(0, 10000) })
    });
  } catch (e) {}
}
// Daily cron: diff the sitemaps against the last-seen URL set and ping only NEW urls (new blog posts,
// new pages after a build+deploy — anything that lands in a sitemap gets announced within a day).
async function checkIndexNow(env, force) {
  try {
    const day = new Date().toISOString().slice(0, 10);
    if (!force && (await env.STATS.get('inow:day')) === day) return; // once per UTC day (force bypasses)
    await env.STATS.put('inow:day', day);
    let urls = [];
    for (const sm of ['https://marginpad.io/sitemap.xml', 'https://marginpad.io/community/sitemap.xml']) {
      try { const t = await (await fetch(sm)).text(); urls = urls.concat([...t.matchAll(/<loc>([^<]+)<\/loc>/g)].map(m => m[1].trim())); } catch (e) {}
    }
    urls = [...new Set(urls)].filter(u => u.startsWith('https://marginpad.io'));
    if (!urls.length) return;
    const seenRaw = await env.STATS.get('inow:seen');
    if (!seenRaw) { await env.STATS.put('inow:seen', JSON.stringify(urls)); return; } // first run seeds only (full set was submitted manually 2026-07-16)
    const seen = new Set(JSON.parse(seenRaw));
    const fresh = urls.filter(u => !seen.has(u));
    if (fresh.length) await indexNowPing(fresh);
    await env.STATS.put('inow:seen', JSON.stringify(urls));
  } catch (e) {}
}

async function handleComm(url, request, env, ctx) {
  const jh = { 'content-type': 'application/json; charset=utf-8', 'cache-control': 'no-store' };
  const jr = (o, st) => new Response(JSON.stringify(o), { status: st || 200, headers: jh });
  if (!env.COMM) return jr({ error: 'unavailable' }, 503);
  const path = url.pathname.replace('/api/comm', '') || '/';
  const stub = env.COMM.get(env.COMM.idFromName('main'));
  const tok = getCookie(request, SESS_COOKIE);
  const su = tok && env.USERS ? await sessionUser(env, tok) : null;
  let uid = su && su.id ? String(su.id) : '';
  let author = su ? String(su.username || '') : '';
  if (request.method === 'POST' && (path === '/post' || path === '/comment' || path === '/like' || path === '/mark' || path === '/follow')) {
    if (!uid) return jr({ error: 'login_required' }, 401);
    if (su.status && su.status !== 'active') return jr({ error: 'restricted' }, 403);
    if ((path === '/post' || path === '/comment') && (su.muted || (',' + String(su.restrictions || '') + ',').indexOf(',chat,') >= 0)) return jr({ error: 'restricted' }, 403);
    if ((path === '/post' || path === '/comment') && !author) return jr({ error: 'need_username' }, 400);
  }
  let admin = false;
  if (path === '/admin') { admin = await adminCookieOk(request, env); if (!admin) return jr({ error: 'forbidden' }, 403); }
  // anonymous feed reads collapse to one DO hit per colo per 20s (same pattern as the reward leaderboard cache)
  if (request.method === 'GET' && path === '/feed' && !uid) {
    const ck = new Request('https://marginpad.io/__comm_feed_v1?' + url.searchParams.toString());
    try { const hit = await caches.default.match(ck); if (hit) return new Response(hit.body, { headers: jh }); } catch (e) {}
    const r = await stub.fetch(new Request('https://do/feed?' + url.searchParams.toString()));
    const txt = await r.text();
    if (r.status === 200) try { await caches.default.put(ck, new Response(txt, { headers: { 'content-type': 'application/json', 'cache-control': 'public, max-age=20' } })); } catch (e) {}
    return new Response(txt, { headers: jh });
  }
  const rawBody = request.method === 'POST' ? await request.text() : undefined;
  const fwd = new Request('https://do' + path + (request.method === 'GET' ? url.search : ''), {
    method: request.method,
    headers: { 'content-type': 'application/json', 'x-uid': uid, 'x-author': author, 'x-admin': admin ? '1' : '0' },
    body: rawBody,
  });
  let r = null, txt = '';
  for (let attempt = 0; attempt < 2; attempt++) { // a DO reset mid-flight (every deploy) throws "internal error" — retry GETs once, never POSTs (a post/like must not double-fire)
    try { r = await stub.fetch(fwd.clone ? fwd.clone() : fwd); txt = await r.text(); break; } catch (e) { r = null; if (request.method === 'POST') break; }
  }
  if (!r) return jr({ error: 'busy', transient: true }, 503);
  // instant owner visibility: Telegram ping on every published post (owner asked to SEE when someone posts)
  if (path === '/post' && request.method === 'POST' && r.status === 200 && env.TELEGRAM_TOKEN && env.TG_ADMIN_CHAT && ctx) {
    try {
      const d = JSON.parse(txt); const pb = JSON.parse(rawBody || '{}');
      if (d && d.ok && d.id) {
        const safe = x => String(x || '').replace(/[<>&]/g, '');
        ctx.waitUntil(tgApi(env.TELEGRAM_TOKEN, 'sendMessage', { chat_id: env.TG_ADMIN_CHAT, parse_mode: 'HTML', disable_web_page_preview: true, text: '\u270d\ufe0f <b>New community post</b> by ' + safe(author) + '\n' + safe(pb.title).slice(0, 120) + '\n\nhttps://marginpad.io/community/p/' + d.id }).catch(() => {}));
        ctx.waitUntil(indexNowPing(['https://marginpad.io/community/p/' + d.id + '/' + commSlug(pb.title)])); // search engines learn about the post immediately
      }
    } catch (e) {}
  }
  if (request.method === 'POST' && path === '/post' && r && r.status === 200) { try { const _pd = JSON.parse(txt); if (_pd && !_pd.error) { const pr2 = evPush(env, request, 'post', author, '/community/'); if (ctx && ctx.waitUntil) ctx.waitUntil(pr2); else await pr2; } } catch (e) {} }
  // surface community actions in the live activity feed (comment always; like/save/follow only when they TURN ON, not off)
  if (request.method === 'POST' && r && r.status === 200 && (path === '/comment' || path === '/follow' || path === '/like' || path === '/mark')) { try { const _cd = JSON.parse(txt); if (_cd && !_cd.error) {
    const push = (type, label) => { const pr = evPush(env, request, type, label, '/community/'); if (ctx && ctx.waitUntil) ctx.waitUntil(pr); else return pr; };
    if (path === '/comment') await push('comment', '');
    else if (path === '/like' && _cd.liked) await push('like', '');
    else if (path === '/mark' && _cd.marked) await push('save', '');
    else if (path === '/follow' && _cd.following) { let tn = ''; try { tn = String((JSON.parse(rawBody || '{}').tname) || '').slice(0, 24); } catch (e) {} await push('follow', tn); }
  } } catch (e) {} }
  return new Response(txt, { status: r.status, headers: jh });
}
async function commPage(url, request, env) {
  // /community/p|u|c/* : serve the community shell with per-route SEO head; post pages get the article server-rendered for crawlers
  let shell = '';
  try { const sr = await env.ASSETS.fetch(new Request(url.origin + '/community/')); shell = await sr.text(); } catch (e) {}
  if (!shell) return new Response('community unavailable', { status: 503 });
  let html = shell;
  const setMeta = (title, desc, canon) => {
    html = html.replace(/<title>[^<]*<\/title>/, '<title>' + escH(title) + '</title>');
    html = html.replace(/(<meta name="description" content=")[^"]*(")/, '$1' + escH(desc).replace(/"/g, '&quot;') + '$2');
    html = html.replace(/(<link rel="canonical" href=")[^"]*(")/, '$1' + canon + '$2');
    html = html.replace(/(<meta property="og:title" content=")[^"]*(")/, '$1' + escH(title).replace(/"/g, '&quot;') + '$2');
    html = html.replace(/(<meta property="og:description" content=")[^"]*(")/, '$1' + escH(desc).replace(/"/g, '&quot;') + '$2');
    html = html.replace(/(<meta property="og:url" content=")[^"]*(")/, '$1' + canon + '$2');
  };
  let m;
  if ((m = url.pathname.match(/^\/community\/p\/([a-z0-9]{6,20})/i))) {
    try {
      const r = await env.COMM.get(env.COMM.idFromName('main')).fetch(new Request('https://do/post?id=' + m[1]));
      const d = await r.json();
      if (d && d.post) {
        const p = d.post;
        const canon = 'https://marginpad.io/community/p/' + p.id + '/' + commSlug(p.title);
        const desc = String(p.body || '').replace(/[#*`>\[\]]/g, '').replace(/\s+/g, ' ').trim().slice(0, 158);
        setMeta(p.title + ' — MarginPad Community', desc, canon);
        const ld = { '@context': 'https://schema.org', '@type': 'SocialMediaPosting', headline: p.title, datePublished: new Date(p.ts).toISOString(), author: { '@type': 'Person', name: p.author, url: 'https://marginpad.io/community/u/' + encodeURIComponent(p.author) }, publisher: { '@type': 'Organization', name: 'MarginPad' }, mainEntityOfPage: canon, commentCount: p.ncom, interactionStatistic: { '@type': 'InteractionCounter', interactionType: 'https://schema.org/LikeAction', userInteractionCount: p.likes } };
        const crumb = { '@context': 'https://schema.org', '@type': 'BreadcrumbList', itemListElement: [{ '@type': 'ListItem', position: 1, name: 'Home', item: 'https://marginpad.io/' }, { '@type': 'ListItem', position: 2, name: 'Community', item: 'https://marginpad.io/community/' }, { '@type': 'ListItem', position: 3, name: p.title, item: canon }] };
        const ssr = '<article class="ssr-post"><div class="pcrumb"><a href="/community/">Community</a> / <a href="/community/c/' + escH(p.cat) + '">' + escH(COMM_CATS[p.cat] || p.cat) + '</a></div><h1>' + escH(p.title) + '</h1><div class="pmeta">by <a href="/community/u/' + encodeURIComponent(p.author) + '">' + escH(p.author) + '</a> · ' + new Date(p.ts).toISOString().slice(0, 10) + ' · ' + (p.likes || 0) + ' likes · ' + (p.ncom || 0) + ' comments</div><div class="pbody">' + commMd(p.body) + '</div></article>'
          + '<script type="application/ld+json">' + JSON.stringify(ld).replace(/</g, '\\u003c') + '</script>'
          + '<script type="application/ld+json">' + JSON.stringify(crumb).replace(/</g, '\\u003c') + '</script>';
        html = html.replace('<!--SSR-->', ssr);
      } else { setMeta('Post not found — MarginPad Community', 'This community post does not exist or was removed.', 'https://marginpad.io/community/'); }
    } catch (e) {}
  } else if ((m = url.pathname.match(/^\/community\/u\/([^\/]{3,40})/))) {
    const who = decodeURIComponent(m[1]).replace(/[^A-Za-z0-9_.-]/g, '').slice(0, 30);
    setMeta(who + ' — trader profile | MarginPad Community', who + "'s trading ideas, market analysis and discussions on the MarginPad community.", 'https://marginpad.io/community/u/' + encodeURIComponent(who));
  } else if ((m = url.pathname.match(/^\/community\/c\/([a-z-]{3,24})/))) {
    const nm = COMM_CATS[m[1]] || m[1];
    setMeta(nm + ' — MarginPad Community', 'Latest ' + nm.toLowerCase() + ' posts and discussions from the MarginPad trading community.', 'https://marginpad.io/community/c/' + m[1]);
  } else if (url.pathname === '/community/sitemap.xml') {
    let items = [];
    try { const r = await env.COMM.get(env.COMM.idFromName('main')).fetch(new Request('https://do/sitemap')); const d = await r.json(); items = (d && d.posts) || []; } catch (e) {}
    const xml = '<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">\n'
      + '  <url><loc>https://marginpad.io/community/</loc><changefreq>hourly</changefreq><priority>0.9</priority></url>\n'
      + Object.keys(COMM_CATS).map(c => '  <url><loc>https://marginpad.io/community/c/' + c + '</loc><changefreq>daily</changefreq><priority>0.6</priority></url>').join('\n') + '\n'
      + items.map(p => '  <url><loc>https://marginpad.io/community/p/' + p.id + '/' + commSlug(p.title) + '</loc><lastmod>' + new Date(p.ts).toISOString().slice(0, 10) + '</lastmod></url>').join('\n')
      + '\n</urlset>';
    return new Response(xml, { headers: { 'content-type': 'application/xml; charset=utf-8', 'cache-control': 'public, max-age=3600' } });
  }
  return new Response(html, { headers: { 'content-type': 'text/html; charset=utf-8', 'cache-control': 'no-store' } });
}
